const crypto = require('crypto');
const headers = $json.headers || {};
const payload = $json.body || {};
const timestamp = String(headers['x-workflow-timestamp'] || '');
const nonce = String(headers['x-workflow-nonce'] || '');
const received = String(headers['x-workflow-signature'] || '');
const path = '/webhook/rss-intake-run-v1';
const body = JSON.stringify(payload);
const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, digest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const previousSecret = $env.WORKFLOW_HMAC_PREVIOUS_SECRET;
if (!secret || !timestamp || !nonce || !received) throw new Error('Workflow signature is missing');
const authentic = [secret, previousSecret].filter(Boolean).some((candidate) => {
  const expected = `sha256=${crypto.createHmac('sha256', candidate).update(canonical, 'utf8').digest('hex')}`;
  return received.length === expected.length && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
});
if (!authentic) throw new Error('Workflow signature is invalid');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Workflow signature expired');
if (payload.contractVersion !== '1.0' || !payload.actorId || !payload.brandId || !payload.correlationId || !payload.idempotencyKey || !payload.requestedAt) throw new Error('One-off RSS intake contract is invalid');
return [{ json: payload }];

const crypto = require('crypto');
const path = '/api/internal/workflows/rss/feeds';
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomUUID();
const body = '';
const bodyDigest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'GET', path, bodyDigest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.APP_BASE_URL;
if (!secret || !baseUrl) throw new Error('Required workflow environment is not configured');
const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
const brandQuery = $json.brandId ? `?brandId=${encodeURIComponent($json.brandId)}` : '';
return [{ json: { url: `${baseUrl}${path}${brandQuery}`, timestamp, nonce, signature } }];

const crypto = require('crypto');
const feed = $json.feed;
const path = '/api/internal/workflows/rss/fetch';
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomUUID();
const correlationId = crypto.randomUUID();
const payload = {
  contractVersion: '1.0',
  correlationId,
  feedId: feed.feedId,
  idempotencyKey: `rss-fetch:${feed.feedId}:${timestamp}`,
  requestedAt: new Date().toISOString(),
};
const body = JSON.stringify(payload);
const bodyDigest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, bodyDigest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.APP_BASE_URL;
if (!secret || !baseUrl) throw new Error('Required workflow environment is not configured');
const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
return { json: { body, correlationId, nonce, signature, timestamp, url: `${baseUrl}${path}` } };

const crypto = require('crypto');
const item = $json.item;
const path = '/api/internal/workflows/rss/intake';
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomUUID();
const correlationId = crypto.randomUUID();
const stableGuidHash = crypto.createHash('sha256').update(item.guid, 'utf8').digest('hex');
const payload = {
  contractVersion: '1.0',
  correlationId,
  idempotencyKey: `rss-item:${$json.feedId}:${stableGuidHash}`,
  feedId: $json.feedId,
  guid: item.guid,
  title: item.title,
  contentHash: item.contentHash,
  requestedAt: new Date().toISOString(),
};
if (item.canonicalUrl) payload.canonicalUrl = item.canonicalUrl;
if (item.author) payload.author = item.author;
if (item.publishedAt) payload.publishedAt = item.publishedAt;
if (item.summary) payload.summary = item.summary;
const body = JSON.stringify(payload);
const bodyDigest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, bodyDigest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.APP_BASE_URL;
if (!secret || !baseUrl) throw new Error('Required workflow environment is not configured');
const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
return { json: { body, nonce, signature, timestamp, url: `${baseUrl}${path}` } };

